<?php
namespace App\Http\Controllers; use App\Models\Project; use Illuminate\Http\Request;
class ProjectController extends Controller { private function own(Project $p){abort_unless($p->user_id===auth()->id(),403);} public function index(){return view('projects.index',['projects'=>Project::withCount('tasks')->where('user_id',auth()->id())->latest()->get()]);} public function create(){return view('projects.create',['project'=>new Project]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:150','description'=>'nullable']);$d['user_id']=auth()->id();Project::create($d);return redirect()->route('projects.index')->with('success','Project dibuat.');} public function show(Project $project){$this->own($project);$project->load('tasks');return view('projects.show',compact('project'));} public function edit(Project $project){$this->own($project);return view('projects.create',compact('project'));} public function update(Request $r,Project $project){$this->own($project);$project->update($r->validate(['name'=>'required|max:150','description'=>'nullable']));return redirect()->route('projects.show',$project)->with('success','Project diperbarui.');} public function destroy(Project $project){$this->own($project);$project->delete();return redirect()->route('projects.index')->with('success','Project dihapus.');} }
